it("rolls Benefits source and current IAM changes back with original evidence receipt audit and outbox before exact retry",async()=>{
 await benefitsPurchase();vi.stubEnv("ERPX_PEOPLE_PACKAGE_ENFORCEMENT","enforced");const dependent=await createBenefitDependent(f.claimant,{name:"Actual held evidence",relationship:"parent",birthDate:"1960-01-01"},key()),id=String(dependent.id),files=await seedAttachmentSet(db,f.owner,{targetType:"benefit_dependent",targetId:id,componentKind:"action",componentRef:"verification",purposeKey:"dependent_proof",expectedTargetVersion:1}),input={action:"verify",expectedVersion:1,reason:"Independent source and evidence verified",attachmentSetIds:[files.setId]},tables=["benefit_dependents","benefit_dependent_events","attachment_sets","attachment_links","attachment_events","command_receipts","audit_events","outbox_events","assignments","hr_people","hr_engagements"],snapshot=()=>Promise.all(tables.map(async table=>(await db.prepare(`SELECT row_to_json(r)::text image FROM ${table} r ORDER BY row_to_json(r)::text`).all()).results));
 for(const fault of ["source","authority"] as const){const command=key(),fn=`benefits_final_${key().replaceAll("-","")}`,before=await snapshot(),effect=fault==="source"?`UPDATE hr_people SET status='inactive',version=version+1 WHERE id=(SELECT person_id FROM benefit_dependents WHERE id='${id}')`:`UPDATE assignments SET revoked_at=1,version=version+1 WHERE id='${f.owner.assignmentId}'`;await db.exec(`CREATE SEQUENCE ${fn}_attempt;CREATE FUNCTION ${fn}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM nextval('${fn}_attempt');${effect};RETURN NEW;END $$;CREATE CONSTRAINT TRIGGER ${fn} AFTER INSERT ON command_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.command_id='${command}') EXECUTE FUNCTION ${fn}()`);try{await expect(changeBenefitRecord(f.owner,"dependent",id,input,command)).rejects.toMatchObject({code:fault==="source"?"BENEFIT_SOURCE_CHANGED":"PEOPLE_ACCESS_CHANGED"});expect(await snapshot()).toEqual(before);expect(await db.prepare(`SELECT is_called FROM ${fn}_attempt`).first("is_called")).toBe(true);}finally{await db.exec(`DROP TRIGGER ${fn} ON command_receipts;DROP FUNCTION ${fn}();DROP SEQUENCE ${fn}_attempt`);}}
 const command=key(),saved=await changeBenefitRecord(f.owner,"dependent",id,input,command);expect(await changeBenefitRecord(f.owner,"dependent",id,input,command)).toEqual(saved);expect(await attachmentBindingState(db,files.setId)).toMatchObject({set_state:"bound",link_state:"bound",binding_type:"benefits_dependent_verify"});
});
