 await benefitsPurchase();await benefitsPurchase("draining");const metric=await queryMetric(db,f.claimant,"active-benefit-elections",filters);expect(metric.total).toBe("2");expect((await queryMetric(db,f.claimant,"published-benefit-plans",filters)).total).toBe("1");const snapshot=await readExecutiveMetricProjection(db,f.claimant,"active-benefit-elections",filters,"default");expect((await snapshot.source({label:metric.rows[0].label,page:1})).rows.map(row=>row.id)).toEqual([own.id]);const evidence=await searchExecutiveEvidence(db,f.claimant,{metric:"active-benefit-elections",filters,limit:1});expect(evidence.items.map(row=>row.id)).toEqual([own.id]);expect(JSON.stringify(await readExecutiveEvidence(db,f.claimant,"active-benefit-elections",String(own.id),filters))).not.toMatch(/employee_deduction_minor|employer_cost_minor|person_id|engagement_id/);await expect(readExecutiveEvidence(db,f.claimant,"active-benefit-elections",String(other.id),filters)).rejects.toMatchObject({status:404});await db.prepare("UPDATE assignments SET modules_json='[\"people_payroll\"]' WHERE id=?").bind(f.claimant.assignmentId).run();await expect(snapshot.source({label:metric.rows[0].label,page:1})).rejects.toMatchObject({code:"METRIC_SOURCE_UNAVAILABLE"});expect((await metricCatalogFor(db,f.claimant)).find(row=>row.id==="active-benefit-elections")?.available).toBe(false);
