it.each(['disabled','enforced'] as const)('buffers original Benefits private files with complete worker and enrollment sources (%s)',async mode=>{
 const {attachmentContent,bindRecordAttachmentSet}=await import('../../../src/server/modules/files/public/attachments/service');
 const {plan,win}=await reviewedSources('employee'),dependent=await createBenefitDependent(f.claimant,{name:'Native private dependent',relationship:'child',birthDate:'2018-01-01'},key()),election=await createBenefitElection(f.claimant,{planId:plan.id,planVersion:2,windowId:win.id,windowVersion:2,dependentIds:[]},key());
 await benefitsPurchase();vi.stubEnv('ERPX_PEOPLE_PACKAGE_ENFORCEMENT',mode);
 for(const source of [{actor:f.owner,targetType:'benefit_plan',targetId:String(plan.id),purposeKey:'benefit_booklet',table:'benefit_plans',version:2},{actor:f.claimant,targetType:'benefit_dependent',targetId:String(dependent.id),purposeKey:'dependent_proof',table:'benefit_dependents',version:1},{actor:f.claimant,targetType:'benefit_election',targetId:String(election.id),purposeKey:'election_document',table:'benefit_elections',version:1}] as const){
  const document=await seedAttachmentSet(db,source.actor,{...source,componentKind:'record',expectedTargetVersion:source.version});await bindRecordAttachmentSet(db,source.actor,document.setId,source.version,key());
  const objectKey=await db.prepare('SELECT object_key FROM attachments WHERE id=?').bind(document.sourceId).first<string>('object_key');if(!objectKey)throw Error('ACTUAL_PRIVATE_BENEFITS_DOCUMENT_REQUIRED');const bytes=`Original retained ${source.targetType} evidence`;await env.H001_FILES.put(objectKey,bytes);let consumed=0;
  const files:FileStore={put:(...args)=>env.H001_FILES.put(...args),get:async(...args)=>{const value=await env.H001_FILES.get(...args);return value?{...value,arrayBuffer:async()=>{consumed++;return value.arrayBuffer();}}:null;},head:(...args)=>env.H001_FILES.head(...args),delete:(...args)=>env.H001_FILES.delete(...args),list:(...args)=>env.H001_FILES.list(...args)};
  const tables=['benefit_plans','benefit_enrollment_windows','benefit_dependents','benefit_elections','hr_people','hr_engagements','attachments','attachment_links','attachment_access_events','assignments'],snapshot=()=>Promise.all(tables.map(async table=>(await db.prepare(`SELECT row_to_json(r)::text image FROM ${table} r ORDER BY row_to_json(r)::text`).all()).results));
  const faults=source.targetType==='benefit_dependent'?['record','worker','file','iam'] as const:['record','worker','plan','file','iam'] as const;
  for(const kind of faults){
   const fault=`benefit_private_${key().replaceAll('-','')}`,effect=kind==='record'?`UPDATE ${source.table} SET version=version+1 WHERE id='${source.targetId}'`:kind==='worker'?`UPDATE hr_people SET legal_name='Late private worker name' WHERE company_id='${f.company}' AND user_id='${source.actor.userId}'`:kind==='plan'?`UPDATE benefit_plans SET name='Late private reviewed plan' WHERE id='${plan.id}'`:kind==='file'?`UPDATE attachments SET legal_hold=1 WHERE id='${document.sourceId}'`:`UPDATE assignments SET revoked_at=1,version=version+1 WHERE id='${source.actor.assignmentId}'`,before=await snapshot();
   await db.exec(`CREATE FUNCTION ${fault}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN ${effect};RETURN NEW;END $$;CREATE CONSTRAINT TRIGGER ${fault} AFTER INSERT ON attachment_access_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.link_id='${document.linkId}' AND NEW.outcome='allowed') EXECUTE FUNCTION ${fault}()`);
   try{await expect(attachmentContent(db,files,source.actor,document.linkId,'original')).rejects.toMatchObject({code:'BENEFIT_FILE_READ_CHANGED'});expect(await snapshot()).toEqual(before);}finally{await db.exec(`DROP TRIGGER ${fault} ON attachment_access_events;DROP FUNCTION ${fault}()`);}
  }
  expect(consumed).toBe(faults.length);await db.prepare('UPDATE attachments SET legal_hold=1 WHERE id=?').bind(document.sourceId).run();expect(await(await attachmentContent(db,files,source.actor,document.linkId,'original')).object.text()).toBe(bytes);expect(consumed).toBe(faults.length+1);
  await expect(db.transaction(tx=>attachmentContent(tx,files,source.actor,document.linkId,'original'))).rejects.toMatchObject({code:'BENEFIT_FILE_READ_TRANSACTION_REQUIRED'});expect(consumed).toBe(faults.length+1);
 }
 await benefitsPurchase('draining');expect((await benefitsWorkspace(f.claimant,true)).elections.map(row=>row.id)).toContain(election.id);
});
it('waits for actual Benefits review before its byte snapshot and isolates two Company document source writers',async()=>{
 const {attachmentContent,bindRecordAttachmentSet}=await import('../../../src/server/modules/files/public/attachments/service'),{committedSourceVisibility}=await import('../../support/helpers/source-writer-visibility'),{companyPurchaseReadLocks}=await import('../../../src/server/modules/commercial/public/purchase-command-boundary'),{measureReads}=await import('../../../src/server/modules/runtime/public/runtime/read-metrics');
 const first=f,dependent=await createBenefitDependent(first.claimant,{name:'Actual source review private evidence',relationship:'child',birthDate:'2018-01-01'},key()),file=await seedAttachmentSet(db,first.claimant,{targetType:'benefit_dependent',targetId:String(dependent.id),componentKind:'record',purposeKey:'dependent_proof',expectedTargetVersion:1});await bindRecordAttachmentSet(db,first.claimant,file.setId,1,key());const objectKey=await db.prepare('SELECT object_key FROM attachments WHERE id=?').bind(file.sourceId).first<string>('object_key');if(!objectKey)throw Error('ACTUAL_PRIVATE_BENEFITS_REVIEW_REQUIRED');await env.H001_FILES.put(objectKey,'Original reviewed dependent evidence');
 const fault=`benefit_visible_${key().replaceAll('-','')}`;await db.exec(`CREATE FUNCTION ${fault}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (SELECT status FROM benefit_dependents WHERE id='${dependent.id}')<>'verified' THEN RAISE EXCEPTION 'STALE_NATIVE_BENEFITS_READ';END IF;RETURN NEW;END $$;CREATE CONSTRAINT TRIGGER ${fault} AFTER INSERT ON attachment_access_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.link_id='${file.linkId}' AND NEW.outcome='allowed') EXECUTE FUNCTION ${fault}()`);
 try{const observed=await committedSourceVisibility(db,async tx=>{await tx.batch(companyPurchaseReadLocks(tx,first.company));benefitsDatabase=tx;try{await changeBenefitRecord(first.owner,'dependent',String(dependent.id),{action:'verify',expectedVersion:2,reason:'Independent native review commits before private document snapshot'},key());}finally{benefitsDatabase=undefined;}},()=>measureReads(()=>attachmentContent(db,env.H001_FILES,first.claimant,file.linkId,'original')));expect(await observed.result.object.text()).toBe('Original reviewed dependent evidence');expect(observed.metrics.deadlockFailures??0).toBe(0);expect(observed.metrics.serializationFailures??0).toBe(0);expect(observed.metrics.transactionRetries??0).toBe(0);}finally{benefitsDatabase=undefined;await db.exec(`DROP TRIGGER ${fault} ON attachment_access_events;DROP FUNCTION ${fault}()`);}
 f=await expenseFixture();for(const actor of [f.owner,f.tie,f.claimant])actor.modules=['benefits','people_payroll'];const other=await createBenefitDependent(f.claimant,{name:'Second Company actual private dependent',relationship:'child',birthDate:'2018-01-01'},key()),otherFile=await seedAttachmentSet(db,f.claimant,{targetType:'benefit_dependent',targetId:String(other.id),componentKind:'record',purposeKey:'dependent_proof',expectedTargetVersion:1});await bindRecordAttachmentSet(db,f.claimant,otherFile.setId,1,key());const otherObject=await db.prepare('SELECT object_key FROM attachments WHERE id=?').bind(otherFile.sourceId).first<string>('object_key');if(!otherObject)throw Error('SECOND_COMPANY_PRIVATE_BENEFITS_REQUIRED');await env.H001_FILES.put(otherObject,'Second Company private evidence');
 const rows:{actor:WorkContext;id:string;file:Awaited<ReturnType<typeof seedAttachmentSet>>;bytes:string}[]=[{actor:first.claimant,id:String(dependent.id),file,bytes:'Original reviewed dependent evidence'},{actor:f.claimant,id:String(other.id),file:otherFile,bytes:'Second Company private evidence'}],parallel=`benefit_bytes_parallel_${key().replaceAll('-','')}`;
 await db.exec(`CREATE FUNCTION ${parallel}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_sleep(0.08);UPDATE benefit_dependents SET name=name WHERE id=CASE WHEN NEW.company_id='${first.company}' THEN '${rows[0].id}' ELSE '${rows[1].id}' END;RETURN NEW;END $$;CREATE CONSTRAINT TRIGGER ${parallel} AFTER INSERT ON attachment_access_events DEFERRABLE INITIALLY DEFERRED FOR EACH ROW WHEN(NEW.link_id IN ('${rows[0].file.linkId}','${rows[1].file.linkId}') AND NEW.outcome='allowed') EXECUTE FUNCTION ${parallel}()`);
 try{const observed=await measureReads(()=>Promise.all(rows.map(row=>attachmentContent(db,env.H001_FILES,row.actor,row.file.linkId,'original'))));for(let index=0;index<rows.length;index++)expect(await observed.result[index].object.text()).toBe(rows[index].bytes);expect(observed.metrics.deadlockFailures??0).toBe(0);expect(observed.metrics.serializationFailures??0).toBe(0);expect(observed.metrics.transactionRetries??0).toBe(0);}finally{await db.exec(`DROP TRIGGER ${parallel} ON attachment_access_events;DROP FUNCTION ${parallel}()`);}
});

